def _address_bytes(base_addr: int, value: int) -> tuple[tuple[int, int], ...]:
    return tuple(
        (base_addr + byte_index, byte)
        for byte_index, byte in enumerate(value.to_bytes(20, "big"))
    )


ARITHMETIC_0X00_CASES = [
    # IR: ADD, STOP
    InstructionRefinementCase(
        name="ADD",
        evm_kind="ADD",
        arity=2,
        x86_core_hex=X86_ADD_CORE_HEX_SEQUENCE,
        base_addr=X86_CORE_BASE_ADDR,
    ),
    # IR: SUB, STOP
    InstructionRefinementCase(
        name="SUB",
        evm_kind="SUB",
        arity=2,
        x86_core_hex=X86_SUB_CORE_HEX_SEQUENCE,
        base_addr=X86_CORE_BASE_ADDR,
        evm_operand_indices=(1, 0),
    ),
    # IR: MUL, STOP
    InstructionRefinementCase(
        name="MUL",
        evm_kind="MUL",
        arity=2,
        x86_core_hex=X86_MUL_CORE_HEX_SEQUENCE,
        base_addr=X86_CORE_BASE_ADDR,
        x86_execution_mode="cfg",
        x86_summary_config=X86SummaryConfig.enabled(mul="strict"),
        solver_timeout_ms=5_000,
    ),
    # IR: DIV, STOP
    # common/arithmetic.div_semantics 已镜像 holiman uint256 的分段实现（快路径
    # limb 展开 + 大数 Knuth 长除法折未解释函数），与 x86 codegen 逐分支对齐。
    # 用逐终止路径比较（x86_compare_terminal_paths）避免 merge 后的大 ITE，
    # 各路径都不再需要 bit-blast 256-bit 除法即可 UNSAT。
    # 相等借位链桥接 assumption 现由 EVM/x86 侧 MOD/DIV 语义经 state.add_assumption
    # 自动挂上（与主路径统一来源），assert_instruction_refines 会收集注入提速。DIV 另挂
    # x86_div64_quotient_fits_assumption 提速 x86 `div r64` guard；它不是 EVM DIV 语义。
    InstructionRefinementCase(
        name="DIV",
        evm_kind="DIV",
        arity=2,
        x86_core_hex=X86_DIV_CORE_HEX_SEQUENCE,
        base_addr=X86_CORE_BASE_ADDR,
        evm_operand_indices=(1, 0),
        x86_execution_mode="cfg",
        x86_enable_go_bridge=True,
        x86_compare_terminal_paths=True,
        expected_stack_height=1,
        # 逐路径都是确定性 unsat；timeout 留足余量，避免全量 suite 满负载下个别
        # 路径抖动触发 unknown。
        solver_timeout_ms=30_000,
    ),
    # IR: MOD, STOP
    # 同 DIV：common/arithmetic.mod_semantics 镜像 holiman 分段实现，逐终止路径比较。
    InstructionRefinementCase(
        name="MOD",
        evm_kind="MOD",
        arity=2,
        x86_core_hex=X86_MOD_CORE_HEX_SEQUENCE,
        base_addr=X86_CORE_BASE_ADDR,
        evm_operand_indices=(1, 0),
        x86_execution_mode="cfg",
        x86_enable_go_bridge=True,
        x86_compare_terminal_paths=True,
        expected_stack_height=1,
        solver_timeout_ms=30_000,
    ),
    # IR: SDIV, STOP
    # common/arithmetic.sdiv_semantics 镜像 holiman Int.SDiv 的符号分段：按 x、y 符号
    # 分类，绝对值用 0-x（_abs256 用 limb 级带借位减法，对齐 x86 SUBQ/SBBQ），核心复用
    # 已转正的 unsigned div_semantics。x86 codegen（compileEVMSDiv）同构（符号分类树内部调
    # compileEVMDivWithReg）。慢路径靠 _verified_div_bridges 配对两侧 div + 求解器的
    # simplify+bit-blast tactic（见 _make_refinement_solver）逐终止路径 UNSAT。
    InstructionRefinementCase(
        name="SDIV",
        evm_kind="SDIV",
        arity=2,
        x86_core_hex=X86_SDIV_CORE_HEX_SEQUENCE,
        base_addr=X86_CORE_BASE_ADDR,
        evm_operand_indices=(1, 0),
        x86_execution_mode="cfg",
        x86_enable_go_bridge=True,
        x86_compare_terminal_paths=True,
        expected_stack_height=1,
        # 逐路径都是确定性 unsat（tactic 单路径 ≤十几秒）；timeout 留足余量，避免全量
        # suite 满负载 CPU 争抢下个别路径 wall-clock 超时触发 unknown。
        solver_timeout_ms=60_000,
    ),
    # IR: SMOD, STOP
    # 同 SDIV：common/arithmetic.smod_semantics 镜像 holiman Int.SMod（余数符号取被除数
    # x 符号，复用已转正的 unsigned mod_semantics），逐终止路径比较。SMOD 早退路径（如
    # |x|<|y| → 结果=|x|）x86 不含 div，靠 _make_refinement_solver 的 simplify+bit-blast
    # tactic 把取负/分段 ITE 折掉求解（默认 smt 策略会 unknown）。
    InstructionRefinementCase(
        name="SMOD",
        evm_kind="SMOD",
        arity=2,
        x86_core_hex=X86_SMOD_CORE_HEX_SEQUENCE,
        base_addr=X86_CORE_BASE_ADDR,
        evm_operand_indices=(1, 0),
        x86_execution_mode="cfg",
        x86_enable_go_bridge=True,
        x86_compare_terminal_paths=True,
        expected_stack_height=1,
        # 同 SDIV：留足 timeout 余量，避免满负载抖动 unknown。
        solver_timeout_ms=60_000,
    ),
    # IR: ADDMOD, STOP
    # EVM 侧分段镜像见 common/arithmetic.addmod_semantics。逐终止路径比较
    # （x86_compare_terminal_paths）避免 merge 大 ITE，各路径无需 bit-blast 257-bit 除法
    # 即可 UNSAT；相等借位链桥接 hint 由两侧语义自动挂上，同 MOD 范式。
    InstructionRefinementCase(
        name="ADDMOD",
        evm_kind="ADDMOD",
        arity=3,
        x86_core_hex=X86_ADDMOD_CORE_HEX_SEQUENCE,
        base_addr=X86_CORE_BASE_ADDR,
        evm_operand_indices=(2, 1, 0),
        x86_execution_mode="cfg",
        x86_enable_go_bridge=True,
        x86_compare_terminal_paths=True,
        expected_stack_height=1,
        # 逐路径都是确定性 unsat；timeout 留足余量，避免全量 suite 满负载下个别路径
        # 抖动触发 unknown（同 DIV/MOD）。
        solver_timeout_ms=30_000,
    ),
    # IR: MULMOD, STOP
    InstructionRefinementCase(
        name="MULMOD",
        evm_kind="MULMOD",
        arity=3,
        x86_core_hex=X86_MULMOD_CORE_HEX_SEQUENCE,
        base_addr=X86_CORE_BASE_ADDR,
        evm_operand_indices=(2, 1, 0),
        x86_execution_mode="cfg",
        x86_enable_go_bridge=True,
        solver_timeout_ms=15_000,
    ),
    # IR: EXP, STOP
    InstructionRefinementCase(
        name="EXP",
        evm_kind="EXP",
        arity=2,
        x86_core_hex=X86_EXP_CORE_HEX_SEQUENCE,
        base_addr=X86_CORE_BASE_ADDR,
        evm_operand_indices=(1, 0),
        x86_execution_mode="cfg",
        x86_enable_go_bridge=True,
        solver_timeout_ms=1_000,
    ),
    # IR: SIGNEXTEND, STOP
    pytest.param(
        InstructionRefinementCase(
            name="SIGNEXTEND",
            evm_kind="SIGNEXTEND",
            arity=2,
            x86_core_hex=X86_SIGNEXTEND_CORE_HEX_SEQUENCE,
            base_addr=X86_CORE_BASE_ADDR,
            evm_operand_indices=(1, 0),
            x86_execution_mode="cfg",
            solver_timeout_ms=1_000,
        ),
        marks=pytest.mark.xfail(
            reason=BRANCHY_CFG_XFAIL_REASON,
            strict=True,
        ),
    ),
]


